from itertools import combinations
import random

def check_graph(edges, n=9):
    """Check if a graph satisfies all constraints."""
    # Build adjacency list
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    # Check min degree >= 2
    degrees = [len(adj[i]) for i in range(n)]
    if min(degrees) < 2:
        return False, "min degree < 2"

    # Check max degree <= 4
    if max(degrees) > 4:
        return False, "max degree > 4"

    # Check edge count between 11 and 17
    if len(edges) < 11 or len(edges) > 17:
        return False, f"edge count {len(edges)} not in [11, 17]"

    # Check chromatic number = 3
    # First check if 2-colorable (bipartite)
    def is_bipartite():
        color = [-1] * n
        for start in range(n):
            if color[start] == -1:
                color[start] = 0
                queue = [start]
                while queue:
                    u = queue.pop(0)
                    for v in adj[u]:
                        if color[v] == -1:
                            color[v] = 1 - color[u]
                            queue.append(v)
                        elif color[v] == color[u]:
                            return False
        return True

    if is_bipartite():
        return False, "chromatic number = 2 (bipartite)"

    # Check if 3-colorable
    def is_3_colorable():
        colors = [-1] * n
        def backtrack(v):
            if v == n:
                return True
            for c in range(3):
                valid = True
                for u in adj[v]:
                    if u < v and colors[u] == c:
                        valid = False
                        break
                if valid:
                    colors[v] = c
                    if backtrack(v + 1):
                        return True
                    colors[v] = -1
            return False
        return backtrack(0)

    if not is_3_colorable():
        return False, "chromatic number > 3"

    return True, "valid"

